from typing import List

def is_valid(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char == '*':
            stack.append('*')
        else:
            if not stack:
                return False
            top = stack.pop()
            if char != top and (top != '*' or char not in mapping):
                return False

    while stack:
        top = stack.pop()
        if top == '*':
            continue
        if not stack or stack[-1] != mapping[top]:
            return False
        stack.pop()

    return len(stack) == 0
